DIALOGS = [
[anyone, "legate_sq_2_01", [], "Knowing your enemy is vital to victory, isn't it ? Though considering your condition in this war... very well, I shall gift you with this knowledge. I was born in Casius province of the empire, as first and only son of Lucian Marius, the previous Legate. My mother was an elegant woman from one of the noble houses of Aden, or so I've been told - I never knew her, since she died during my birth. ", "legate_sq_2_02", [] ],
]
